@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;600;700&family=Source+Serif+4:opsz,wght@8..60,400;8..60,600;8..60,700&display=swap');
:root{--ink:#17130e;--paper:#f3e7cd;--paper2:#fbf3df;--gold:#c99635;--gold2:#e6bd63;--dark:#090d0b;--line:#bda576;--game:#8ea6b8;--hoc:#b6a07a;--alliance:#8d6da1}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#090d0b;color:#f0e4cf;font-family:'Source Serif 4',Georgia,serif}a{color:inherit}
.site-header{height:72px;background:#080b09;border-bottom:1px solid #69532d;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:24px;padding:0 30px;position:sticky;top:0;z-index:50}.brand{display:flex;align-items:center;gap:12px;text-decoration:none}.brand-mark{width:54px;height:40px;border:1px solid #c79634;display:grid;place-items:center;color:#d9aa50;font:600 20px Cinzel}.brand-name{font:600 16px Cinzel;color:#eee3cf}.site-nav{display:flex;gap:27px;align-items:center;justify-content:center;white-space:nowrap}.site-nav a{text-decoration:none;font:600 11px Cinzel;color:#efe5d2}.site-nav a.active,.site-nav a:hover{color:#d8aa45}.flags{display:flex;justify-content:flex-end;gap:9px;padding-left:18px;border-left:1px solid #3d3425}.flags a{width:28px;height:20px;display:grid;place-items:center}.flags svg{width:26px;height:17px;display:block}.menu-toggle{display:none}
.hero{height:220px;position:relative;overflow:hidden;border-bottom:1px solid #6f592f;background:#0d110f}.hero::before{content:'';position:absolute;inset:0;background-image:linear-gradient(90deg,rgba(4,7,6,.72),rgba(4,7,6,.25) 62%,rgba(4,7,6,.12)),url('data:image/png;base64,');background-position:center;background-size:cover;background-repeat:no-repeat}.hero-inner{position:relative;height:100%;max-width:1500px;margin:auto;padding:0 34px;display:flex;flex-direction:column;justify-content:center}.eyebrow{margin:0 0 7px;color:#d6a13b;font:600 11px Cinzel;letter-spacing:.18em}.hero h1{margin:0;color:#efc66f;font:600 clamp(42px,4vw,61px) Cinzel;letter-spacing:.01em}.hero p{max-width:720px;margin:9px 0 0;color:#f6ead7;font-size:17px;line-height:1.35}
main{padding:15px 17px 0}.page-shell{width:min(1500px,100%);margin:auto;display:grid;grid-template-columns:minmax(0,1fr) 345px;gap:16px;align-items:start}.calendar-card,.daily-card{background:var(--paper);border:1px solid #c9ae7b;box-shadow:0 0 0 5px rgba(119,88,40,.12) inset;color:var(--ink)}.calendar-inner{padding:17px 17px 0}.ornament{display:flex;justify-content:center;align-items:center;gap:12px;color:#a77725;margin:0 0 15px}.ornament span{font:600 13px Cinzel;letter-spacing:.12em}.ornament h2{margin:0;font:600 24px Cinzel;color:#17130e}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:14px}.controls{display:flex;align-items:center;gap:7px}button{font-family:inherit}.square,.today{height:35px;border:1px solid #8c6829;background:#18150f;color:#f3dfb8;font:600 11px Cinzel;cursor:pointer}.square{width:38px;font-size:18px}.today{padding:0 15px}.range{height:35px;min-width:292px;border:1px solid #b9a57c;background:#fcf5e7;color:#1c170f;display:flex;align-items:center;justify-content:space-between;padding:0 10px;font:600 10px Cinzel}.legend{display:flex;gap:15px;align-items:center;flex-wrap:wrap}.legend span{display:flex;gap:6px;align-items:center;font:600 9px 'Source Serif 4';color:#5b4d3a}.legend i{width:11px;height:11px;border-radius:3px;display:block}.legend .game{background:#315d7c}.legend .hoc{background:#a47c26}.legend .alliance{background:#704a87}
.week-head{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid #d1bd97;border-bottom:0}.day{height:39px;border:0;border-right:1px solid #5c503e;background:#30291f;color:#f4e8d5;font:600 10px Cinzel;cursor:pointer}.day:last-child{border-right:0}.day.selected{background:#e5bd63;color:#20180d}.timeline{position:relative;overflow:hidden;border:1px solid #d1bd97;border-top:0;background:repeating-linear-gradient(to right,transparent 0,transparent calc(16.6667% - .5px),#d9c8a6 calc(16.6667% - .5px),#d9c8a6 calc(16.6667% + .5px)),repeating-linear-gradient(to bottom,transparent 0 49px,#e1d4b8 49px 50px)}.event-row{position:absolute;left:0;width:100%;height:50px}.event-bar{position:absolute;top:5px;height:40px;display:flex;align-items:center;gap:9px;padding:0 8px 0 7px;min-width:82px;clip-path:polygon(0 0,calc(100% - 14px) 0,100% 50%,calc(100% - 14px) 100%,0 100%,9px 50%);box-shadow:0 2px 5px rgba(0,0,0,.18)}.event-icon{width:35px;height:35px;flex:0 0 35px;border-radius:50%;overflow:hidden;display:grid;place-items:center;background:#d4c1a0;border:1px solid rgba(45,32,16,.6)}.event-icon img{width:100%;height:100%;display:block;object-fit:cover}.event-label{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:600 10px Cinzel;letter-spacing:.01em}.event-time{margin-left:auto;white-space:nowrap;padding:4px 6px;background:rgba(28,21,13,.3);border:1px solid rgba(255,255,255,.25);font:600 8px Cinzel}.amber{background:#96382e;color:#fff0dc}.return{background:#58758f;color:#fff}.elite,.army{background:#766049;color:#fff}.trade{background:#b7a07b;color:#211910}.mobil{background:#8c6ca0;color:#fff}.fireworks{background:#9c6840;color:#fff}.winter{background:#567592;color:#fff}.battle{background:#79654f;color:#fff}.navigator{background:#50624b;color:#fff}.smoke{background:#2f7773;color:#fff}.night{background:#315d86;color:#fff}.advisor{background:#91352e;color:#fff}
.upcoming{margin-top:13px;background:#0b0f0c;border:1px solid #58482e;padding:14px 14px 15px;color:#eee0c7}.upcoming h2{margin:0 0 11px;color:#d4a03d;font:600 15px Cinzel}.upcoming-grid{display:grid;grid-template-columns:repeat(4,1fr)}.up-item{display:grid;grid-template-columns:45px 1fr;gap:8px;padding:4px 11px;border-right:1px solid #4d422e;min-width:0}.up-item:last-child{border-right:0}.up-item .event-icon{width:40px;height:40px}.up-item h3{margin:1px 0 3px;color:#f1e3ca;font:600 9px Cinzel}.up-item p{margin:0;color:#cfbd9d;font-size:9px;line-height:1.25}.full{display:inline-block;margin-top:12px;padding:9px 13px;border:1px solid #99722b;color:#e1b44e;text-decoration:none;font:600 9px Cinzel}
.sidebar{min-width:0}.daily-card{padding:13px}.daily-inner{border:1px solid #d0ba8c;padding:12px 12px 13px}.daily-date{height:35px;border:1px solid #c6ae80;background:#fcf4e2;display:grid;place-items:center;margin-bottom:9px;color:#33271a;font:600 9px Cinzel}.daily-list{display:grid;gap:6px}.daily-item{min-height:42px;display:flex;align-items:center;gap:8px;padding:4px 6px;clip-path:polygon(0 0,calc(100% - 11px) 0,100% 50%,calc(100% - 11px) 100%,0 100%,8px 50%);box-shadow:0 2px 4px rgba(0,0,0,.16)}.daily-item .event-icon{width:34px;height:34px;flex-basis:34px}.daily-copy{min-width:0;flex:1;display:flex;align-items:center;justify-content:space-between;gap:6px}.daily-copy strong{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:600 8px Cinzel}.daily-copy small{white-space:nowrap;padding:3px 5px;background:rgba(26,20,12,.28);font:600 7px Cinzel}.daily-section-title{margin:12px 0 8px;text-align:center;color:#a77725;font:600 10px Cinzel;letter-spacing:.08em}.mini-week{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid #cdb68a}.mini-day{border:0;border-right:1px solid #d8c5a4;background:#fbf2de;color:#3a2d1e;padding:5px 2px;cursor:pointer}.mini-day:last-child{border-right:0}.mini-day b{display:block;font:600 7px Cinzel}.mini-day strong{display:block;margin-top:2px;font:700 10px Cinzel}.mini-day.selected{background:#e4ba60}.daily-vignette{margin-top:9px;aspect-ratio:375/135;border:1px solid #b99a62;background:url('data:image/png;base64,') center/cover no-repeat}.daily-button{display:block;text-align:center;margin-top:9px;background:#17140f;color:#e3b64f;border:1px solid #8e682b;padding:10px;text-decoration:none;font:600 9px Cinzel}
.info-strip{width:min(1500px,100%);margin:13px auto 0;background:#0b0e0c;border:1px solid #5b4a2f;display:grid;grid-template-columns:repeat(4,1fr) 1.1fr;color:#eadfc8}.info-strip article,.info-note{padding:13px;border-right:1px solid #443a2a}.info-strip article{display:grid;grid-template-columns:38px 1fr;gap:9px}.info-note{background:#ead9b8;color:#2d2418}.info-icon{width:34px;height:34px;border:1px solid #bd892b;color:#d5a03c;display:grid;place-items:center;font:600 18px Cinzel}.info-strip h3{margin:0 0 4px;color:#d4a03d;font:600 9px Cinzel}.info-note h3{color:#6d4a15}.info-strip p{margin:0;color:#d4c5a9;font-size:9px;line-height:1.35}.info-note p{color:#40321f}.footer{text-align:center;padding:10px;color:#987d4b;font:500 8px Cinzel;letter-spacing:.08em}
@media(max-width:1150px){.site-header{padding:0 18px}.site-nav{gap:13px}.site-nav a{font-size:9px}.page-shell{grid-template-columns:minmax(0,1fr) 310px}.upcoming-grid{grid-template-columns:repeat(2,1fr)}.up-item:nth-child(2){border-right:0}.up-item:nth-child(3),.up-item:nth-child(4){border-top:1px solid #4d422e}.info-strip{grid-template-columns:repeat(2,1fr)}.info-note{grid-column:1/-1;border-top:1px solid #443a2a}}
@media(max-width:900px){.site-header{height:68px;display:flex;padding:0 14px;flex-wrap:wrap}.brand{order:1}.flags{order:2;margin-left:auto;border-left:0;padding-left:0}.menu-toggle{order:3;display:block;margin-left:10px;background:#121510;color:#f3e5c7;border:1px solid #c99635;padding:8px 11px;font:600 10px Cinzel;cursor:pointer}.site-nav{display:none;position:absolute;left:0;right:0;top:68px;background:#080b09;border-bottom:1px solid #c99635;padding:16px;flex-direction:column;align-items:center;gap:14px;z-index:60}.site-nav.open{display:flex}.page-shell{grid-template-columns:1fr}.hero{height:215px}.hero-inner{padding:0 22px}.sidebar{order:2}.info-strip{width:100%}}
@media(max-width:600px){.brand-name{display:none}.brand-mark{width:47px}.flags a{width:27px}.flags svg{width:25px;height:16px}.hero{height:205px}.hero h1{font-size:35px}.hero p{font-size:15px}main{padding:10px 9px 0}.calendar-inner{padding:14px 10px 0}.ornament h2{font-size:18px}.toolbar{flex-direction:column;align-items:stretch}.controls{width:100%;flex-wrap:wrap}.range{min-width:0;flex:1}.legend{justify-content:flex-start}.day{font-size:8px}.event-row{height:49px}.event-bar{height:38px}.event-icon{width:29px;height:29px;flex-basis:29px}.event-label{font-size:7px}.event-time{font-size:6px;padding:3px 4px}.upcoming-grid{grid-template-columns:1fr}.up-item{border-right:0;border-bottom:1px solid #4d422e}.up-item:nth-child(3),.up-item:nth-child(4){border-top:0}.mini-day b{font-size:6px}.mini-day strong{font-size:9px}.daily-item{min-height:38px}.daily-item .event-icon{width:28px;height:28px;flex-basis:28px}.daily-copy strong{font-size:7px}.daily-copy small{font-size:6px}.info-strip{grid-template-columns:1fr}.info-note{grid-column:auto}.info-strip article{border-right:0;border-top:1px solid #443a2a}.info-strip article:first-child{border-top:0}}
